body.zh:
import { z } from "zod";

const Env = z.object({ DATABASE_URL: z.string().url(), PORT: z.coerce.number() });
export const env = Env.parse(process.env); // 缺失或格式不对 → 启动即失败
// 之后到处用 env.PORT(number),不再直接读 process.env

body.en:
import { z } from "zod";

const Env = z.object({ DATABASE_URL: z.string().url(), PORT: z.coerce.number() });
export const env = Env.parse(process.env); // missing or malformed -> fails at startup
// from here on use env.PORT (number), never process.env directly
